source = source.replace('</head>', CSS + JS + '\n</head>', 1)
OUTPUT.write_text(source, encoding="utf-8", newline="\n")

checks = {
    "output": OUTPUT.exists() and OUTPUT.stat().st_size > 90000,
    "same search": "Hommybuscando.png" in source and "Buscar Cliente" in source,
    "real history endpoint": "HISTORIAL_CLIENTE" in source,
    "real client list": "listaClientes=1" in source,
    "protected preview permission": "'clientes-conectado-v31.html': 'clientes.read'" in source,
    "inline guard": 'id="clientes-v31-inline-guard"' in source,
    "brand color": "#B2566C" in source,
    "real icons": "fa-solid fa-phone" in source and "fa-location-dot" in source and "fa-regular fa-envelope" in source,
    "real logo": "triangulogold.png" in source,
    "orders": "buildOrder" in source,
    "quotes": "buildQuote" in source,
    "payments": "buildPayments" in source and "abonos_detalle" in source,
    "pdf": "abrirVisorPDF" in source,
    "edit": "abrirModalEditar" in source,
    "self search path": "window.location.pathname + '?search='" in source,
}
failed = [name for name, ok in checks.items() if not ok]
if failed: raise SystemExit("Contratos fallidos: " + ", ".join(failed))
print(f"Generado {OUTPUT.name}: {OUTPUT.stat().st_size} bytes")
for name in checks: print("OK", name)
